+use react::*;
+use std::cell::Cell;
+
+#[test]
+fn compute_cells_update_through_chains() {
+    let mut reactor = Reactor::new();
+    let input = reactor.create_input(1);
+    let times_two = reactor
+        .create_compute(&[CellId::Input(input)], |v| v[0] * 2)
+        .unwrap();
+    let times_thirty = reactor
+        .create_compute(&[CellId::Input(input)], |v| v[0] * 30)
+        .unwrap();
+    let output = reactor
+        .create_compute(
+            &[CellId::Compute(times_two), CellId::Compute(times_thirty)],
+            |v| v[0] + v[1],
+        )
+        .unwrap();
+    assert_eq!(reactor.value(CellId::Compute(output)), Some(32));
+    assert!(reactor.set_value(input, 3));
+    assert_eq!(reactor.value(CellId::Compute(output)), Some(96));
+}
+
+#[test]
+fn create_compute_rejects_nonexistent_dependency() {
+    let mut dummy = Reactor::new();
+    let missing = dummy.create_input(1);
+    let mut reactor = Reactor::<i32>::new();
+    assert_eq!(
+        reactor.create_compute(&[CellId::Input(missing)], |_| 0),
+        Err(CellId::Input(missing))
+    );
+    assert!(!reactor.set_value(missing, 2));
+    assert_eq!(reactor.value(CellId::Input(missing)), None);
+}
+
+#[test]
+fn callbacks_fire_once_with_final_value_only_on_change() {
+    let calls = Cell::new(0);
+    let last = Cell::new(None);
+    let never = Cell::new(0);
+    let mut reactor = Reactor::new();
+    let input = reactor.create_input(1);
+    let plus_one = reactor
+        .create_compute(&[CellId::Input(input)], |v| v[0] + 1)
+        .unwrap();
+    let minus_one = reactor
+        .create_compute(&[CellId::Input(input)], |v| v[0] - 1)
+        .unwrap();
+    let always_two = reactor
+        .create_compute(
+            &[CellId::Compute(plus_one), CellId::Compute(minus_one)],
+            |v| v[0] - v[1],
+        )
+        .unwrap();
+    let parity = reactor
+        .create_compute(&[CellId::Input(input)], |v| v[0] % 2)
+        .unwrap();
+    reactor
+        .add_callback(always_two, |_| never.set(never.get() + 1))
+        .unwrap();
+    reactor
+        .add_callback(parity, |v| {
+            calls.set(calls.get() + 1);
+            last.set(Some(v));
+        })
+        .unwrap();
+
+    reactor.set_value(input, 3);
+    assert_eq!(calls.get(), 0);
+    reactor.set_value(input, 4);
+    assert_eq!((calls.get(), last.get()), (1, Some(0)));
+    assert_eq!(never.get(), 0);
+}
+
+#[test]
+fn removed_callbacks_stop_firing_and_cannot_be_removed_twice() {
+    let calls = Cell::new(0);
+    let mut reactor = Reactor::new();
+    let input = reactor.create_input(1);
+    let output = reactor
+        .create_compute(&[CellId::Input(input)], |v| v[0] + 1)
+        .unwrap();
+    let callback = reactor
+        .add_callback(output, |_| calls.set(calls.get() + 1))
+        .unwrap();
+    reactor.set_value(input, 2);
+    assert_eq!(reactor.remove_callback(output, callback), Ok(()));
+    reactor.set_value(input, 3);
+    assert_eq!(calls.get(), 1);
+    assert_eq!(
+        reactor.remove_callback(output, callback),
+        Err(RemoveCallbackError::NonexistentCallback)
+    );
+
+    let mut other = Reactor::new();
+    let other_input = other.create_input(1);
+    let other_output = other
+        .create_compute(&[CellId::Input(other_input)], |v| v[0])
+        .unwrap();
+    let mut empty = Reactor::<i32>::new();
+    assert_eq!(
+        empty.remove_callback(other_output, callback),
+        Err(RemoveCallbackError::NonexistentCell)
+    );
+    assert!(empty.add_callback(other_output, |_| {}).is_none());
+}

